package com.lqq.supportflow.knowledge.application;
import com.lqq.supportflow.knowledge.domain.*; import java.io.*; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
@Service public class UploadKnowledgeDocumentService { private static final long MAX_FILE_SIZE=20L*1024*1024; private final KnowledgeObjectStorage storage; private final DocumentTextExtractor extractor; private final RegisterKnowledgeDocumentService registration; private final KnowledgeDocumentPort documents; public UploadKnowledgeDocumentService(KnowledgeObjectStorage storage,DocumentTextExtractor extractor,RegisterKnowledgeDocumentService registration,KnowledgeDocumentPort documents){this.storage=storage;this.extractor=extractor;this.registration=registration;this.documents=documents;} public KnowledgeDocument upload(Long tenantId,Long knowledgeBaseId,MultipartFile file){if(file.isEmpty())throw new IllegalArgumentException("document file is empty");if(file.getSize()>MAX_FILE_SIZE)throw new IllegalArgumentException("document file exceeds 20 MB");try{byte[] bytes=file.getBytes();String hash=ContentHasher.sha256(bytes);String type=file.getContentType()==null?"application/octet-stream":file.getContentType();StoredKnowledgeObject stored=storage.put(tenantId,knowledgeBaseId,hash,file.getOriginalFilename(),type,new ByteArrayInputStream(bytes),bytes.length);String text;try(InputStream input=storage.open(stored.objectKey())){text=extractor.extract(input,type);}KnowledgeDocument document=registration.registerExtracted(tenantId,knowledgeBaseId,file.getOriginalFilename(),hash,text);documents.attachObject(tenantId,document.id(),stored.objectKey(),type);return document;}catch(IOException exception){throw new IllegalArgumentException("cannot read uploaded document",exception);}}}
